<?php
require_once __DIR__.'/auth.php';require_admin();
$totalProducts=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$activeProducts=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn();$categoryCount=(int)$pdo->query('SELECT COUNT(*) FROM categories')->fetchColumn();$pendingOrders=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='pending_confirmation'")->fetchColumn();
$lowStockThreshold=(int)($pdo->query("SELECT setting_value FROM store_settings WHERE setting_key='low_stock_threshold'")->fetchColumn()?:5);$lowStockCount=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock_qty IS NOT NULL AND stock_qty<='.$lowStockThreshold)->fetchColumn();
$today=new DateTimeImmutable('today');$dailyMap=[];$monthlyMap=[];
foreach($pdo->query("SELECT DATE(created_at) d,COUNT(*) c,COALESCE(SUM(CASE WHEN status<>'cancelled' THEN total ELSE 0 END),0) revenue FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at)")->fetchAll() as $r)$dailyMap[$r['d']]=$r;
foreach($pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') m,COUNT(*) c,COALESCE(SUM(CASE WHEN status<>'cancelled' THEN total ELSE 0 END),0) revenue FROM orders WHERE created_at>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),'%Y-%m-01') GROUP BY DATE_FORMAT(created_at,'%Y-%m')")->fetchAll() as $r)$monthlyMap[$r['m']]=$r;
$daily=[];for($i=6;$i>=0;$i--){$date=$today->modify("-$i days")->format('Y-m-d');$daily[]=['label'=>date('d.m',strtotime($date)),'orders'=>(int)($dailyMap[$date]['c']??0),'revenue'=>(float)($dailyMap[$date]['revenue']??0)];}
$monthly=[];for($i=5;$i>=0;$i--){$date=$today->modify("first day of this month -$i months");$key=$date->format('Y-m');$monthly[]=['label'=>$date->format('m/Y'),'orders'=>(int)($monthlyMap[$key]['c']??0),'revenue'=>(float)($monthlyMap[$key]['revenue']??0)];}
$pageTitle='Dashboard';$current='dashboard';require __DIR__.'/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">GENEL BAKIŞ</p><h1>Dashboard</h1><p class="text-secondary">Mağazanızın güncel durumu ve satış eğilimleri.</p></div><a class="btn btn-primary" href="<?=e(app_url('admin/products/add.php'))?>">＋ Yeni ürün ekle</a></div>
<div class="row g-3 mb-4"><div class="col-sm-6 col-xl-3"><div class="stat-card"><span class="stat-icon purple">◇</span><span class="stat-label">Toplam ürün</span><strong><?=$totalProducts?></strong><small>Kataloğunuzdaki ürünler</small></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><span class="stat-icon green">✓</span><span class="stat-label">Aktif ürün</span><strong><?=$activeProducts?></strong><small>Yayında olan ürünler</small></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><span class="stat-icon orange">!</span><span class="stat-label">Stok uyarısı</span><strong><?=$lowStockCount?></strong><small>Stok <?=$lowStockThreshold?> adet veya altında</small></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><span class="stat-icon orange">▤</span><span class="stat-label">Kategori</span><strong><?=$categoryCount?></strong><small>Ürün kategorileri</small></div></div></div>
<div class="content-card mb-4"><div class="card-heading d-flex justify-content-between align-items-center"><div><h2>Satış ve ciro</h2><p>İptal siparişleri cirodan çıkarılmıştır.</p></div><div class="btn-group"><button class="btn btn-sm btn-primary" type="button" data-chart-tab="daily">Günlük</button><button class="btn btn-sm btn-outline-primary" type="button" data-chart-tab="monthly">Aylık</button></div></div>
<?php foreach(['daily'=>$daily,'monthly'=>$monthly] as $kind=>$series):$maxOrders=max(1,...array_column($series,'orders'));$maxRevenue=max(1,...array_column($series,'revenue'));?><div data-chart-panel="<?=$kind?>" <?=$kind==='monthly'?'hidden':''?>><div class="d-flex justify-content-between small text-secondary mb-2"><span>Sipariş sayısı</span><span>₺ ciro</span></div><div class="d-flex align-items-end gap-2" style="height:190px;border-bottom:1px solid #dce3da;padding:0 4px"><?php foreach($series as $point):$orderHeight=$point['orders']?max(6,(int)round($point['orders']/$maxOrders*100)):2;$revenueHeight=$point['revenue']?max(6,(int)round($point['revenue']/$maxRevenue*100)):2;?><div class="text-center flex-fill" style="min-width:24px"><div class="d-flex align-items-end justify-content-center gap-1" style="height:150px"><span title="<?=$point['orders']?> sipariş" style="display:block;width:10px;height:<?=$orderHeight?>%;background:#e3a844;border-radius:4px 4px 0 0"></span><span title="₺<?=number_format($point['revenue'],2,',','.')?> ciro" style="display:block;width:10px;height:<?=$revenueHeight?>%;background:#287543;border-radius:4px 4px 0 0"></span></div><small class="d-block text-secondary mt-2"><?=e($point['label'])?></small></div><?php endforeach;?></div><div class="small text-secondary mt-2">Grafik çubuklarının üzerine gelerek sipariş ve ciro değerlerini görün.</div></div><?php endforeach;?></div>
<div class="content-card"><div class="card-heading"><div><h2>Hızlı işlemler</h2><p>Onay bekleyen sipariş: <?=$pendingOrders?></p></div></div><div class="quick-actions"><a href="<?=e(app_url('admin/products/add.php'))?>"><span>＋</span><div><strong>Ürün ekle</strong><small>Kataloğa yeni ürün ekleyin</small></div><b>→</b></a><a href="<?=e(app_url('admin/products/index.php'))?>"><span>◇</span><div><strong>Ürünleri yönet</strong><small>Ürünleri görüntüleyin ve yönetin</small></div><b>→</b></a><a href="<?=e(app_url('admin/orders/index.php'))?>"><span>▣</span><div><strong>Siparişleri yönet</strong><small>Arama, filtreleme ve kargo bilgileri</small></div><b>→</b></a><a href="<?=e(app_url('admin/stock/index.php'))?>"><span>↕</span><div><strong>Stok geçmişi ve talepler</strong><small>Stok uyarıları ve e-posta talepleri</small></div><b>→</b></a></div></div>
<script>document.querySelectorAll('[data-chart-tab]').forEach((button)=>button.addEventListener('click',()=>{document.querySelectorAll('[data-chart-tab]').forEach((b)=>{b.classList.toggle('btn-primary',b===button);b.classList.toggle('btn-outline-primary',b!==button)});document.querySelectorAll('[data-chart-panel]').forEach((panel)=>panel.hidden=panel.dataset.chartPanel!==button.dataset.chartTab)}));</script>
